<template><section class="uto" :class="{'is-client':!adminView}"><h2>{{adminView?$t('团队全景'):$t('团队概览')}}</h2><p v-if="loading">{{ $t("正在获取团队资料…") }}</p><p v-if="error" role="alert">{{ $t(error) }} <button @click="load(page)">{{ $t("重试") }}</button></p><template v-if="team&&!error"><div class="uto-grid"><div><small>{{ $t('个人业绩 USDT') }}</small><b>{{fmt(team.personal_principal_usdt)}}</b></div><div v-if="!adminView"><small>{{ $t('累计团队收益 UMI') }}</small><b>{{fmt(incomeSummary?.by_kind?.team)}}</b></div><div v-if="!adminView"><small>{{ $t('累计推荐收益 UMI') }}</small><b>{{fmt(incomeSummary?.by_kind?.referral)}}</b></div><div><small>{{ $t("直属上级邀请码") }}</small><b>{{team.parent_code||'—'}}</b></div><div><small>{{ $t("直属 / 团队人数") }}</small><b>{{team.direct_count}} / {{team.team_count}}</b></div><div><small>{{ $t("有效团队业绩 USDT") }}</small><b>{{fmt(team.effective_team_usdt)}}</b></div><div><small>{{ $t("最大分支 / 小区 USDT") }}</small><b>{{fmt(team.largest_branch_usdt)}} / {{fmt(team.small_area_usdt)}}</b></div></div><p v-if="adminView">{{team.basis}}</p><div class="uto-level"><b>V{{team.recorded_level}}</b><details><summary>{{ $t('晋级条件') }}</summary><p>{{ $t('当前条件预估') }} V{{team.projected_level}}<span v-if="team.next_level"> · V{{team.next_level}} {{ $t('还需小区业绩') }} {{fmt(team.next_level_gap_usdt)}} USDT</span></p><p v-if="!team.personal_qualification_met">{{ $t('个人有效参与尚未达到 100 USDT。') }}</p></details></div><details><summary>{{ $t("直属分支贡献") }}</summary><div v-for="b in team.branches" :key="b.member_id" class="uto-row"><span>{{b.member_code}}</span><b>{{fmt(b.effective_principal_usdt)}} USDT</b></div></details><h3>{{ $t("团队成员") }}</h3><p v-if="!team.rows.length">{{ $t("暂无下级成员。") }}</p><div v-for="m in team.rows" :key="m.id" class="uto-row"><span>{{m.member_code}} {{ $t("· 第") }} {{m.depth}} {{ $t("层 · V") }}{{m.level}}</span><b>{{fmt(m.effective_principal_usdt)}} USDT</b></div><footer><button :disabled="loading||page<=1" @click="load(page-1)">{{ $t("上一页") }}</button><span>{{page}} / {{team.last_page}}</span><button :disabled="loading||page>=team.last_page" @click="load(page+1)">{{ $t("下一页") }}</button></footer></template></section></template>
<script>
import UmiLocale from '@/Functions/UmiLocale';
import axios from 'axios';import {formatUmi} from '@/Functions/UmiDisplay';
export default {mixins:[UmiLocale],props:{incomeSummary:Object,adminView:Boolean,memberId:[Number,String]},data(){return{team:null,error:'',loading:false,page:1,sequence:0};},watch:{memberId(){this.load(1);}},mounted(){this.load(1);},methods:{fmt:formatUmi,async load(page){const sequence=++this.sequence;this.loading=true;this.error='';try{const r=await axios.get(this.adminView?'/exchange-control-panel/umi/operations/team':'/umi-ecosystem/portfolio/team',{params:{page,...(this.adminView?{member_id:this.memberId}:{})}});if(sequence===this.sequence){this.team=r.data;this.page=page;}}catch(e){if(sequence===this.sequence)this.error=e.response?.data?.message||'团队资料获取失败。';}finally{if(sequence===this.sequence)this.loading=false;}}}};
</script>
<style scoped>.uto.is-client{border-color:#c4cec6;border-radius:12px;padding:16px}.uto.is-client .uto-grid{gap:9px}.uto.is-client .uto-grid>div{background:#f5f7f5;padding:12px;border-radius:9px}.uto.is-client .uto-grid b{font-size:19px;margin-top:5px}.uto.is-client .uto-grid small{font-size:11px}.uto.is-client h2{font-size:16px;margin-bottom:12px}.uto.is-client .uto-level{display:flex;justify-content:space-between;gap:12px;margin:15px 0}.uto.is-client .uto-level>details{text-align:right;font-size:12px}.uto.is-client h3{font-size:14px;margin:20px 0 6px}body.dark .uto.is-client .uto-grid>div{background:#293b2e}.uto{padding:22px;border:1px solid #dfe9e1;border-radius:18px;background:#fff;margin:18px 0}.uto h2{font-size:21px}.uto p{color:#697f70;line-height:1.7}.uto-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.uto-grid small,.uto-grid b{display:block;overflow-wrap:anywhere}.uto-grid small{color:#6b7e71}.uto-row{display:flex;justify-content:space-between;gap:15px;border-bottom:1px solid #e7eee9;padding:12px 0;font-size:13px}.uto footer{display:flex;justify-content:space-between;align-items:center;margin-top:16px}.uto button{padding:8px 12px;border:1px solid #c5d9cb;border-radius:8px;color:#26663b;background:#eef8f1}.uto button:disabled{opacity:.45}body.dark .uto{background:#202a24;border-color:#3c4a40;color:#edf3ee}body.dark .uto p,body.dark .uto small{color:#b6c6ba}body.dark .uto button{background:#2a3b30;color:#d3e9da}@media(max-width:650px){.uto{padding:15px}.uto-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.uto-row{flex-wrap:wrap}}</style>
